83	  private void prepareFileListing(Job job) throws Exception {
84	    if (context.shouldUseSnapshotDiff()) {
85	      // When "-diff" or "-rdiff" is passed, do sync() first, then
86	      // create copyListing based on snapshot diff.
87	      DistCpSync distCpSync = new DistCpSync(context, job.getConfiguration());
88	      if (distCpSync.sync()) {
89	        createInputFileListingWithDiff(job, distCpSync);
90	      } else {
91	        throw new Exception("DistCp sync failed, input options: " + context);
92	      }
93	    } else {
94	      // When no "-diff" or "-rdiff" is passed, create copyListing
95	      // in regular way.
96	      createInputFileListing(job);
97	    }
